grI(){return"\u064a\u064f\u0628\u0642\u064a \u0627\u0644\u0644\u0648\u062d\u0629 \u0636\u0645\u0646 \u0627\u0644\u0645\u0646\u0637\u0642\u0629 \u0627\u0644\u0648\u0627\u0642\u0639\u0629 \u0625\u0644\u0649 \u064a\u0645\u064a\u0646 \u0646\u0642\u0637\u0629 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0648\u0623\u0633\u0641\u0644\u0647\u0627."},
goi(){return"\u0641\u062a\u062d Butterfly \u0641\u064a \u0648\u0636\u0639 \u0645\u0644\u0621 \u0627\u0644\u0634\u0627\u0634\u0629 \u0625\u0630\u0627 \u0623\u0645\u0643\u0646."},
gqi(){return"\u064a\u063a\u064a\u0631 \u0646\u0645\u0637 \u0627\u0644\u0623\u0644\u0648\u0627\u0646 \u0645\u0633\u062a\u0642\u0644\u064b\u0627 \u0639\u0646 \u0627\u0644\u0648\u0636\u0639 \u0627\u0644\u0641\u0627\u062a\u062d \u0623\u0648 \u0627\u0644\u062f\u0627\u0643\u0646 \u0627\u0644\u0645\u062d\u062f\u062f."},
gud(){return"\u0627\u0633\u062a\u062e\u062f\u0645 \u062a\u062e\u0637\u064a\u0637 \u0633\u0637\u062d \u0627\u0644\u0645\u0643\u062a\u0628 \u0623\u0648 \u0627\u0644\u062c\u0648\u0627\u0644 \u0628\u062f\u0644\u0627\u064b \u0645\u0646 \u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0636\u064a \u0644\u062c\u0647\u0627\u0632\u0643."},
gqe(){return"\u064a\u063a\u064a\u0631 \u0627\u0644\u0645\u0633\u0627\u0641\u0629 \u0648\u062d\u062c\u0645 \u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u0648\u0627\u062c\u0647\u0629. \u0644\u0627 \u064a\u063a\u064a\u0631 \u062d\u062c\u0645 \u0645\u062d\u062a\u0648\u0649 \u0645\u0644\u0627\u062d\u0638\u062a\u0643."},
gr5(){return"\u064a\u0633\u062a\u062e\u062f\u0645 \u062a\u0628\u0627\u064a\u0646\u0627\u062a \u0644\u0648\u0646\u064a\u0629 \u0623\u0643\u062b\u0631 \u0648\u0636\u0648\u062d\u064b\u0627 \u0644\u064a\u0633\u0647\u0644 \u062a\u0645\u064a\u064a\u0632 \u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u062a\u062d\u0643\u0645 \u0648\u0627\u0644\u0646\u0635\u0648\u0635."},
gt0(){return"\u064a\u0633\u062a\u062e\u062f\u0645 \u0634\u0631\u064a\u0637 \u0639\u0646\u0648\u0627\u0646 \u0627\u0644\u0646\u0638\u0627\u0645 \u0628\u062f\u0644\u0627\u064b \u0645\u0646 \u0634\u0631\u064a\u0637 \u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0627\u0644\u062e\u0627\u0635 \u0628\u0640 Butterfly."},
guk(){return"\u064a\u062d\u062f\u062f \u0645\u0643\u0627\u0646 \u0644\u0648\u062d\u0629 \u062a\u0639\u062f\u064a\u0644 \u0627\u0644\u0623\u062f\u0627\u0629 \u0623\u0648 \u0627\u0644\u0639\u0646\u0635\u0631 \u0627\u0644\u0645\u062d\u062f\u062f."},
gt2(){return"\u064a\u0639\u0631\u0636 \u0634\u0631\u064a\u0637 \u062a\u0646\u0642\u0644 \u062f\u0627\u0626\u0645 \u0639\u0644\u0649 \u0627\u0644\u0634\u0627\u0634\u0627\u062a \u0627\u0644\u0648\u0627\u0633\u0639\u0629 \u0644\u0644\u0648\u0635\u0648\u0644 \u0627\u0644\u0633\u0631\u064a\u0639 \u0625\u0644\u0649 \u0623\u0642\u0633\u0627\u0645 \u0627\u0644\u062a\u0637\u0628\u064a\u0642\u0627\u062a."},
