go5(){return"\u064a\u062d\u062f\u062f \u0645\u062a\u0649 \u064a\u0638\u0647\u0631 \u0634\u0631\u064a\u0637 \u0627\u0644\u0623\u062f\u0648\u0627\u062a \u0627\u0644\u0623\u0635\u063a\u0631 \u062d\u062c\u0645\u064b\u0627 \u0648\u0627\u0644\u0645\u0628\u0633\u0637 \u0623\u062b\u0646\u0627\u0621 \u062a\u062d\u0631\u064a\u0631 \u0627\u0644\u0645\u0644\u0627\u062d\u0638\u0629."},
gtE(){return'\u064a\u0645\u0646\u0639 \u0638\u0647\u0648\u0631 \u0639\u0644\u0627\u0645\u0627\u062a \u063a\u064a\u0631 \u0645\u0642\u0635\u0648\u062f\u0629 \u0646\u0627\u062a\u062c\u0629 \u0639\u0646 \u064a\u062f\u0643 \u0623\u0648 \u0627\u0644\u0641\u0623\u0631\u0629 \u0645\u0646 \u062e\u0644\u0627\u0644 \u062a\u062d\u062f\u064a\u062f \u0645\u062a\u0649 \u064a\u0645\u0651\u0643\u0646 \u0648\u0636\u0639 "\u0627\u0644\u0642\u0644\u0645 \u0641\u0642\u0637".'},
go_(){return"\u064a\u0639\u0631\u0636 \u062a\u0628\u062f\u064a\u0644\u0627\u064b \u0633\u0631\u064a\u0639\u0627\u064b \u0625\u0644\u0649 \u0648\u0636\u0639  \u201d\u0627\u0644\u0642\u0644\u0645 \u0641\u0642\u0637\u201c \u0641\u064a \u0627\u0644\u0645\u062d\u0631\u0631 \u0639\u0646\u062f\u0645\u0627 \u064a\u0643\u062a\u0634\u0641 Butterfly \u0648\u062c\u0648\u062f \u0642\u0644\u0645."},
grf(){return"\u064a\u062d\u062f\u062f \u0645\u0627 \u0625\u0630\u0627 \u0643\u0627\u0646 \u0644\u0636\u063a\u0637 \u0627\u0644\u0642\u0644\u0645 \u062a\u0623\u062b\u064a\u0631 \u0639\u0644\u0649 \u0634\u0643\u0644 \u0627\u0644\u062e\u0637\u060c \u0643\u0645\u0627 \u064a\u0642\u0644\u0644 \u0645\u0646 \u062a\u0623\u062b\u064a\u0631 \u0642\u0631\u0627\u0621\u0627\u062a \u0627\u0644\u0636\u063a\u0637 \u0627\u0644\u063a\u064a\u0631 \u0627\u0644\u062f\u0642\u064a\u0642\u0629 \u0627\u0644\u062a\u064a \u062a\u0646\u062a\u062c \u0645\u0646 \u0628\u0639\u0636 \u0627\u0644\u0623\u0642\u0644\u0627\u0645."},
grW(){return"\u064a\u062a\u064a\u062d \u0644\u0625\u064a\u0645\u0627\u0621\u0627\u062a \u0627\u0644\u0644\u0645\u0633 \u062a\u062d\u0631\u064a\u0643 \u0627\u0644\u0644\u0648\u062d\u0629 \u0628\u062f\u0644\u0627\u064b \u0645\u0646 \u0627\u0644\u062a\u0641\u0627\u0639\u0644 \u0645\u0639 \u0645\u062d\u062a\u0648\u0649 \u0627\u0644\u0645\u0644\u0627\u062d\u0638\u0629."},
