grf(){return"\u0412\u0438\u0437\u043d\u0430\u0447\u0430\u0454, \u0447\u0438 \u0437\u043c\u0456\u043d\u044e\u0454 \u0441\u0442\u0438\u043b\u044c \u0442\u0438\u0441\u043a\u0443 \u0456 \u043f\u0440\u0430\u0446\u044e\u0454 \u043d\u0430\u0432\u043a\u043e\u043b\u043e \u043d\u0435\u0442\u043e\u0447\u043d\u0438\u0445 \u043f\u043e\u043a\u0430\u0437\u043d\u0438\u043a\u0456\u0432 \u0442\u0438\u0441\u043a\u0443 \u0437 \u0434\u0435\u044f\u043a\u0438\u0445 \u0441\u0442\u0438\u043b\u0456\u0432."},
